onClick:
{{
  Creer_Nouvel_Inventaire.run()
    .then(() => {
      // 1. On rafraîchit la liste des inventaires
      return Get_Inventaires_Actifs.run();
    })
    .then(() => {
      // 2. On affiche un petit message de succès vert en haut
      showAlert('Nouvel inventaire créé avec succès !', 'success');

      // 3. Optionnel : On sélectionne automatiquement le nouvel inventaire dans la liste
      // (Appsmith le fait souvent de base grâce au Default Selected Value qu'on a mis)
    })
    .catch((error) => {
      showAlert('Erreur de création : ' + error.message, 'error');
    });
}}
